import { createServer } from 'node:http'
import { pathToFileURL } from 'node:url'
import { buildReport, createInventory } from './src/report.mjs'

export function createReportServer(items = createInventory()) {
  return createServer((request, response) => {
    if (request.method !== 'GET' || request.url !== '/report') {
      response.writeHead(404).end('not found')
      return
    }
    const report = buildReport(items)
    response.writeHead(200, { 'content-type': 'application/json' })
    response.end(JSON.stringify(report))
  })
}

export function startReportServer(port = 0) {
  const server = createReportServer()
  return new Promise((resolve, reject) => {
    server.once('error', reject)
    server.listen(port, '127.0.0.1', () => {
      const address = server.address()
      if (!address || typeof address === 'string') {
        reject(new Error('server did not expose a TCP address'))
        return
      }
      resolve({ server, url: `http://127.0.0.1:${address.port}` })
    })
  })
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? '').href) {
  const { url } = await startReportServer(Number(process.env.PORT ?? 0))
  console.log(url)
}

export function createInventory(count = 5_000) {
  const regions = ['north', 'south', 'east', 'west']
  const products = Array.from({ length: count }, (_, index) => ({
    productId: `sku-${String(index % 3_700).padStart(4, '0')}`,
    region: regions[index % regions.length],
    warehouse: `warehouse-${index % 7}`,
    units: (index * 17) % 97,
  }))

  return products.concat(products.slice(0, 250))
}

export function buildReport(items) {
  const seen = []
  const report = []

  for (const item of items) {
    const key = `${item.productId}:${item.region}`
    if (seen.includes(key)) continue
    seen.push(key)

    const regionalItems = items.filter((candidate) => candidate.region === item.region)
    const regionalUnits = regionalItems.reduce((sum, candidate) => sum + candidate.units, 0)
    report.push({
      productId: item.productId,
      region: item.region,
      units: item.units,
      share: regionalUnits === 0 ? 0 : item.units / regionalUnits,
    })
  }

  return report.sort(
    (left, right) =>
      right.share - left.share ||
      left.productId.localeCompare(right.productId) ||
      left.region.localeCompare(right.region),
  )
}

import { performance } from 'node:perf_hooks'
import { startReportServer } from './server.mjs'

const { server, url } = await startReportServer()
try {
  for (let index = 0; index < 2; index += 1) {
    await fetch(`${url}/report`).then((response) => response.arrayBuffer())
  }

  const samples = []
  for (let index = 0; index < 7; index += 1) {
    const start = performance.now()
    const response = await fetch(`${url}/report`)
    const body = await response.arrayBuffer()
    if (!response.ok || body.byteLength === 0) throw new Error('report request failed')
    samples.push(Number((performance.now() - start).toFixed(3)))
  }

  const ordered = [...samples].sort((left, right) => left - right)
  console.log(JSON.stringify({ samplesMs: samples, medianMs: ordered[Math.floor(ordered.length / 2)] }))
} finally {
  await new Promise((resolve) => server.close(resolve))
}
import assert from 'node:assert/strict'
import { test } from 'node:test'
import { buildReport } from '../src/report.mjs'

test('report removes duplicate product-region rows and sorts by share then identity', () => {
  const items = [
    { productId: 'b', region: 'north', warehouse: 'one', units: 4 },
    { productId: 'a', region: 'north', warehouse: 'two', units: 4 },
    { productId: 'a', region: 'north', warehouse: 'three', units: 4 },
    { productId: 'c', region: 'south', warehouse: 'one', units: 2 },
  ]
  const report = buildReport(items)
  assert.deepEqual(
    report.map(({ productId, region }) => `${productId}:${region}`),
    ['c:south', 'a:north', 'b:north'],
  )
  assert.equal(report.length, 3)
  assert.deepEqual(Object.keys(report[0]), ['productId', 'region', 'units', 'share'])
})
